/// <summary>
/// NDX Databaselog class sesigned by NDX
/// </summary>
internal final class NDXSysDataBaseLogItemWeightClass extends NDXSysDataBaseLog
{
    NDXSysDataBaseLogItemWeight ndx_Log_ItemWeight;
}

Method.Source:
void deleteRecords(RecId _recIdInventTable)
{
    ndx_Log_ItemWeight = null;

    if (_recIdInventTable)
    {
        delete_from ndx_Log_ItemWeight where ndx_Log_ItemWeight.InventTableRefRecId == _recIdInventTable;
    }
    else
    {
        delete_from ndx_Log_ItemWeight;
    }
}

createdDateTime getLatest()
{
    select firstOnly DateTimeChanged from ndx_Log_ItemWeight order by DateTimeChanged desc;
    return ndx_Log_ItemWeight.DateTimeChanged;
}

void storeValues(InventTable _inventTable)
{
    ndx_Log_ItemWeight.clear();
    ndx_Log_ItemWeight.InventTableRefRecId  = _inventTable.RecId;
    ndx_Log_ItemWeight.DateTimeChanged      = sysDatabaseLog.CreatedDateTime;
    ndx_Log_ItemWeight.Username             = sysDatabaseLog.Username;
    ndx_Log_ItemWeight.NetWeightFrom        = conpeek(con, 3);
    ndx_Log_ItemWeight.NetWeightTo          = conpeek(con, 2);
    ndx_Log_ItemWeight.insert();
    ++nAnz;
}
